with flattened_attrs as (select id, tier_prices, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, aggregate(tier_prices, cast(0 as double), (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, element_at(tier_prices, 1) as entry_price from price_tiers) select case when avg_tier_price >= 34 then 'HIGH' else 'LOW' end as avg_tier_price_tier, case when entry_price >= 28 then 'PREMIUM' else 'STANDARD' end as entry_price_tier, round(avg(entry_price), 2) as avg_entry_price, approx_percentile(avg_tier_price, array(0.25, 0.5, 0.75)) as avg_tier_price_quartiles, count(*) as cnt from flattened_attrs group by avg_tier_price_tier, entry_price_tier order by entry_price_tier nulls first;
